CREATE DATABASE IF NOT EXISTS attendance CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE attendance;
CREATE TABLE IF NOT EXISTS members(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(150) NOT NULL, mandal VARCHAR(150), role VARCHAR(150),
 phone_hash CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS attendance(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id INT UNSIGNED NOT NULL,
 attendance_date DATE NOT NULL, marked_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY one_per_day(member_id,attendance_date),
 CONSTRAINT fk_att_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE
);
